import RNA, random, multiprocessing as mp
sub="((...((....))..((...((....))...))..((....))...))"
def worker(seed):
    random.seed(seed)
    for _ in range(500):
        start=''.join(random.choice('ACGU') for _ in range(len(sub)))
        seq,d=RNA.inverse_fold(start,sub)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==sub:
            return seq
    return None
if __name__=='__main__':
    found=[]
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker,range(3000)):
            if r:
                found.append(r)
                print('SOLVED',r,flush=True)
                if len(found)>=5: 
                    p.terminate(); break
    print('DONE',len(found))
